package com.thenerdcj.island;import com.thenerdcj.FoliaSkyblock;import org.bukkit.entity.Player;import java.util.*;public class IslandUpgradeRecommender{private final FoliaSkyblock plugin;public IslandUpgradeRecommender(FoliaSkyblock p){plugin=p;}public List<UpgradeRecommendation>getRecommendations(Player pl,Island i){Playstyle ps=classify(pl,i);List<UpgradeRecommendation>r=new ArrayList<>();Map<IslandUpgrade,Integer>lv=new HashMap<>();var mgr=plugin.getIslandUpgradeManager();for(var u:IslandUpgrade.values()){int l=mgr.getUpgradeLevel(i,u);if(l>0)lv.put(u,l);}for(IslandUpgrade u:IslandUpgrade.values()){int cl=lv.getOrDefault(u,0);if(cl>=5)continue;double sc=score(u,cl,ps,i);if(sc>0.3)r.add(new UpgradeRecommendation(u,cl,cl+1,sc,reason(u,ps)));}r.sort((a,b)->Double.compare(b.score,a.score));return r.subList(0,Math.min(5,r.size()));}private Playstyle classify(Player pl,Island i){return Playstyle.values()[predict(extract(pl,i))];}private double[]extract(Player pl,Island i){double tx=i.getXp(),d=tx>0?tx:1,m=cx(pl,"MINING")/d,c=cx(pl,"COMBAT")/d,f=cx(pl,"FARMING")/d;return new double[]{m,c,0.5,f,Math.min(1,i.getLevel()/50.),Math.min(1,i.getMemberCount()/10.),0.5,Math.min(1,tx/100000)};}private double cx(Player pl,String cat){return 1000.0;}private double score(IslandUpgrade u,int cl,Playstyle ps,Island i){double s=pm(u,ps);if(u==IslandUpgrade.ISLAND_SIZE&&i.getLevel()>=10)s+=0.3;if(cl==0&&i.getLevel()<5)s*=0.5;if(cl<3)s+=0.2;return Math.max(0,Math.min(1,s));}private double pm(IslandUpgrade u,Playstyle ps){return switch(ps){case MINER->switch(u){case HOPPER_LIMIT,SPAWNER_RATE->0.9;case VAULT_SLOTS,AUTO_SELLER->0.7;case WARDROBE_SLOTS->0.6;default->0.3;};case BUILDER->switch(u){case ISLAND_SIZE,HOPPER_LIMIT->0.9;case VAULT_SLOTS,AUTO_SELLER->0.6;case WARDROBE_SLOTS->0.5;default->0.3;};case FIGHTER->switch(u){case SPAWNER_RATE,MOB_CAP->0.9;case HOPPER_LIMIT,VAULT_SLOTS->0.5;case WARDROBE_SLOTS->0.8;default->0.3;};case FARMER->switch(u){case CROP_GROWTH,AUTO_SELLER,HOPPER_LIMIT->0.9;case VAULT_SLOTS,ISLAND_SIZE->0.5;case WARDROBE_SLOTS->0.8;default->0.3;};case BALANCED->switch(u){case WARDROBE_SLOTS->0.7;default->0.6;};};}private String reason(IslandUpgrade u,Playstyle ps){if(u==IslandUpgrade.WARDROBE_SLOTS)return"Quality of life: easily swap between activity-specific armor and equipment sets";return switch(ps){case MINER->"Great for mining operations and ore generation";case BUILDER->"Essential for large-scale building projects";case FIGHTER->"Boosts combat efficiency and mob farming";case FARMER->"Optimizes crop production and auto-selling";case BALANCED->"Well-rounded upgrade for any playstyle";};}public enum Playstyle{MINER("⛏️ Miner","Focuses on mining and ore generation"),BUILDER("🏗️ Builder","Focuses on construction and expansion"),FIGHTER("⚔️ Fighter","Focuses on combat and mob farming"),FARMER("🌾 Farmer","Focuses on farming and automation"),BALANCED("⚖️ Balanced","Well-rounded progression");private final String d,s;Playstyle(String d,String s){this.d=d;this.s=s;}public String getDisplayName(){return d;}public String getDescription(){return s;}}public static class UpgradeRecommendation{public final IslandUpgrade upgrade;public final int currentLevel,recommendedLevel;public final double score;public final String reason;public UpgradeRecommendation(IslandUpgrade u,int c,int r,double sc,String re){upgrade=u;currentLevel=c;recommendedLevel=r;score=sc;reason=re;}}private static int predict(double[]f){double[][]w={{0.8,0.2,0.3,0.1,0.4,0.5,0.3,0.6},{0.2,0.3,0.8,0.7,0.5,0.6,0.4,0.5},{0.3,0.9,0.2,0.5,0.3,0.4,0.7,0.6},{0.4,0.2,0.7,0.6,0.5,0.5,0.4,0.7},{0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5}};double[]sc=new double[5];for(int i=0;i<5;i++){double t=0;for(int j=0;j<f.length;j++)t+=f[j]*w[i][j];sc[i]=t;}int mi=0;for(int i=1;i<5;i++)if(sc[i]>sc[mi])mi=i;return mi;}}